/**
 * English text normalization: the shared cases generated from Python.
 *
 * `tests/fixtures/g2p/english_normalize_cases.json` records what Python's
 * g2p_en does to the text before its dictionary lookup (generated by
 * `scripts/build_english_normalize_fixture.py`). The C++, Rust and Go ports
 * read the same file; this test holds the JS port (`src/en/normalize.js`) to
 * it:
 *
 * - `numbers`: `normalizeNumbers(input)` must equal `output`;
 * - `tokens`: `normalizeAndTokenize(input)`, lowercased, must equal `tokens`
 *   (the port keeps the case for the CamelCase split; Python lowercases).
 *
 * Run: node --test test/test-english-normalize.js
 */

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import { normalizeAndTokenize, normalizeNumbers } from "../src/en/index.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const FIXTURE = join(
  __dirname,
  "..",
  "..",
  "..",
  "..",
  "tests",
  "fixtures",
  "g2p",
  "english_normalize_cases.json"
);

const cases = JSON.parse(readFileSync(FIXTURE, "utf-8"));

describe("English normalization (english_normalize_cases.json)", () => {
  it("fixture has both sections", () => {
    assert.equal(cases.schema_version, 1);
    assert.ok(cases.numbers.length > 0, "no number cases");
    assert.ok(cases.tokens.length > 0, "no token cases");
  });

  it("normalizeNumbers matches Python for every number case", () => {
    const failures = [];
    for (const { input, output } of cases.numbers) {
      const actual = normalizeNumbers(input);
      if (actual !== output) {
        failures.push(
          `${JSON.stringify(input)}: expected ${JSON.stringify(output)}, got ${JSON.stringify(actual)}`
        );
      }
    }
    assert.deepEqual(failures, [], `${failures.length}/${cases.numbers.length} differ`);
  });

  it("normalizeAndTokenize matches Python for every token case", () => {
    const failures = [];
    for (const { input, tokens } of cases.tokens) {
      const actual = normalizeAndTokenize(input).map((w) => w.toLowerCase());
      if (JSON.stringify(actual) !== JSON.stringify(tokens)) {
        failures.push(
          `${JSON.stringify(input)}: expected ${JSON.stringify(tokens)}, got ${JSON.stringify(actual)}`
        );
      }
    }
    assert.deepEqual(failures, [], `${failures.length}/${cases.tokens.length} differ`);
  });

  it("normalizeAndTokenize keeps the case of the words", () => {
    assert.deepEqual(normalizeAndTokenize("ChatGPT, e.g. Mr. Smith"), [
      "ChatGPT",
      ",",
      "for",
      "example",
      "Mr",
      ".",
      "Smith",
    ]);
  });

  it("reads numbers beyond quintillion digit by digit", () => {
    assert.equal(
      normalizeNumbers("1234567890123456789012"),
      "one two three four five six seven eight nine zero one two three four five six " +
        "seven eight nine zero one two"
    );
  });

  it("turns every Unicode whitespace into a word break", () => {
    for (const text of ["a\tb", "a\nb", "a\r\nb", "a\u00a0b", "a\u3000b", "a\u0085b"]) {
      assert.deepEqual(normalizeAndTokenize(text), ["a", "b"], JSON.stringify(text));
    }
  });

  it("strips accents and drops other characters", () => {
    assert.deepEqual(normalizeAndTokenize("Crème Brûlée"), ["Creme", "Brulee"]);
    assert.deepEqual(normalizeAndTokenize("\u212aelvin"), ["Kelvin"]);
    assert.deepEqual(normalizeAndTokenize("日本 ß æ"), []);
  });
});
